SELECT @RNUM:=@RNUM+1 AS rowNum, originalId AS id, boardId, title, content, fileName1, fileName2, fileName3, regUser, regDate, updateAt FROM ( SELECT id AS originalId, board_id AS boardId, title, content, file_name_1 AS fileName1, file_name_2 AS fileName2, file_name_3 AS fileName3, reg_user AS regUser, reg_date AS regDate, update_at AS updateAt FROM TB_BOARD_POST WHERE delete_at IS NULL AND board_id = #{boardId}
AND title LIKE CONCAT('%', #{keyword}, '%') AND reg_user LIKE CONCAT('%', #{keyword}, '%') AND title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY id ASC ) T, (SELECT @RNUM:=0) R ORDER BY id DESC LIMIT #{startRow}, #{size}

mapper.update:
UPDATE TB_BOARD_POST
SET title = #{title}, content = #{content}, reg_user = #{regUser}, update_at = NOW(),
    file_name_1 = #{fileName1}, file_data_1 = #{fileData1, javaType=[B, jdbcType=BLOB}, file_size_1 = #{fileSize1}, content_type_1 = #{contentType1},
    file_name_2 = #{fileName2}, file_data_2 = #{fileData2, javaType=[B, jdbcType=BLOB}, file_size_2 = #{fileSize2}, content_type_2 = #{contentType2},
    file_name_3 = #{fileName3}, file_data_3 = #{fileData3, javaType=[B, jdbcType=BLOB}, file_size_3 = #{fileSize3}, content_type_3 = #{contentType3}
WHERE id = #{id}

UPDATE TB_BOARD_POST
file_name_1=NULL, file_data_1=NULL, file_size_1=NULL, content_type_1=NULL file_name_2=NULL, file_data_2=NULL, file_size_2=NULL, content_type_2=NULL file_name_3=NULL, file_data_3=NULL, file_size_3=NULL, content_type_3=NULL
WHERE id = #{postId}
